function d_dispersion(P,R){var Q=P.Q||100,u=P.u||3,x=P.x||500,y=P.y||0,sy=P.sy||30,sz=P.sz||15;var C=Q/(Math.PI*sy*sz*u)*Math.exp(-y*y/(2*sy*sy));return{downwind_m:x,concentration:+C.toFixed(6),model:'Gaussian plume (ground-level centerline)'};}

